import * as THREE from 'three';

/**
 * Build a tentacle: `segments` bones chained under a root object.
 * Each bone k (k = 0..segments-1) is offset segLen units along its
 * parent's local +Y axis, so the chain reaches at most
 * segments*segLen from the root.
 */
export function buildTentacle(segments = 8, segLen = 0.8) {
  const root = new THREE.Object3D();
  const bones = [];

  let parent = root;
  for (let k = 0; k < segments; k++) {
    const bone = new THREE.Bone();
    bone.position.set(0, k === 0 ? 0 : segLen, 0);
    parent.add(bone);
    bones.push(bone);
    parent = bone;
  }

  return { root, bones, segments, segLen };
}

/** Driver angle for bone k at time t: pure transport delay of k*DELAY seconds. */
export const AMPLITUDE = 0.6;
export const FREQUENCY = 2.0;
export const DELAY = 0.15;

export function driveAngle(k, t) {
  return AMPLITUDE * Math.sin(FREQUENCY * (t - DELAY * k));
}

/**
 * Drive the chain at time t: bone k's rotation.z follows the driven
 * angle delayed by k*0.15 seconds; the root target angle is the
 * undelayed driver (0.6*sin(2*t)).
 */
export function driveTentacle(state, t) {
  // Root target angle (undelayed driver).
  state.root.rotation.z = driveAngle(0, t);

  for (let k = 0; k < state.bones.length; k++) {
    state.bones[k].rotation.z = driveAngle(k, t);
  }
  return state;
}

/** World-space Y of the tentacle tip (last bone), via world matrices. */
export function tentacleTipY(state) {
  state.root.updateMatrixWorld(true);
  const tip = state.bones[state.bones.length - 1];
  const v = new THREE.Vector3();
  tip.getWorldPosition(v);
  return v.y;
}

