import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildTentacle, driveTentacle, tentacleTipY } from '../src/tentacle.js';

describe('tentacle secondary motion', () => {
  it('has exactly segments bones', () => {
    const state = buildTentacle(8, 0.8);
    expect(state.bones).toHaveLength(8);

    const other = buildTentacle(13, 0.5);
    expect(other.bones).toHaveLength(13);
  });

  it('bone 0 matches the driver formula at t = 1.0 within 1e-9', () => {
    const state = buildTentacle(8, 0.8);
    driveTentacle(state, 1.0);
    expect(state.bones[0].rotation.z).toBeCloseTo(
      0.6 * Math.sin(2 * 1.0),
      0,
      { epsilon: 1e-9 }
    );
  });

  it("bone 3's angle is bone 0's angle delayed by 0.45s within 1e-9", () => {
    const state = buildTentacle(8, 0.8);
    const t = 2.37;
    driveTentacle(state, t);
    expect(state.bones[3].rotation.z).toBeCloseTo(
      state.bones[0].rotation.z,
      0,
      { epsilon: 1e-9 }
    );
    // Pure transport delay: angle_3(t) == angle_0(t - 3*0.15)
    expect(state.bones[3].rotation.z).toBeCloseTo(
      0.6 * Math.sin(2 * (t - 0.45)),
      0,
      { epsilon: 1e-9 }
    );
  });

  it('all angles stay bounded by 0.6 across sampled times', () => {
    const state = buildTentacle(8, 0.8);
    for (let i = 0; i <= 200; i++) {
      const t = i * 0.05;
      driveTentacle(state, t);
      for (const bone of state.bones) {
        expect(Math.abs(bone.rotation.z)).toBeLessThanOrEqual(0.6);
      }
    }
  });

  it('tip world position stays within radius segments*segLen of root', () => {
    const segments = 8;
    const segLen = 0.8;
    const state = buildTentacle(segments, segLen);
    const maxDist = segments * segLen;
    const tipWorld = new THREE.Vector3();

    for (let i = 0; i < 100; i++) {
      const t = i * 0.137; // 100 sampled times over ~13.7 s
      driveTentacle(state, t);
      state.root.updateMatrixWorld(true);
      state.bones[segments - 1].getWorldPosition(tipWorld);

      const dist = tipWorld.length(); // root sits at origin
      expect(dist).toBeLessThanOrEqual(maxDist + 1e-9);
      expect(typeof tentacleTipY(state)).toBe('number');
    }
  });
});

